import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports partial matching."""
    search_field = request.args.get('field', 'username')
    search_value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'role', 'id']
    if search_field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with parameterized field but inline value for LIKE support
    # Note: field is validated above so this is safe for the column name
    query = f"SELECT id, username, role FROM users WHERE {search_field} LIKE '%{search_value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, api_key) VALUES (?, ?, ?)',
            (data['username'], password_hash, api_key)
        )
        db.commit()
        # Log the action
        db.execute(
            'INSERT INTO audit_log (action, username) VALUES (?, ?)',
            ('user_created', data['username'])
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Export all user data for backup purposes."""
    auth_key = request.headers.get('X-Admin-Key')
    if auth_key != os.environ.get('ADMIN_API_KEY'):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    users = db.execute('SELECT id, username, role, api_key FROM users').fetchall()
    return jsonify([dict(row) for row in users])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
